import six
from six.moves import reduce


class ToBool(object):
    """Class tries to convert value to bool type"""
    def __init__(self, skip_none=False):
        """
        :param boolean skip_none: Skip convert if the value is None
        """
        self._skip_none = skip_none

    def convert(self, value):
        """Convert specified value to bool

        :param value: Some value to convert

        :return: Converted value
        :rtype: boolean

        :raise: ConvertError if it is not possible to convert specified value
        """
        if value is None and self._skip_none or isinstance(value, bool):
            return value
        if isinstance(value, six.string_types):
            return self._convert_to_bool(value)
        raise Exception('Object "{}" with value "{}" cannot be converted to bool'.format(type(value).__name__, str(value)))

    def _looks_like_false(self, value):
        if value.lower().strip() == "false":
            return True
        return False

    def _looks_like_true(self, value):
        if value.lower().strip() == "true":
            return True
        return False

    def _convert_to_bool(self, value):
        if self._looks_like_true(value):
            value = True
        elif self._looks_like_false(value):
            value = False
        else:
            raise Exception('Value is from out of range. Available values are (not case sensitive): ${True}, ${False}, true, false')
        return value


def _to_bool(value, skip_none=False):
    """Method to made conversion to boolean

    :param value: Some value to convert
    :param boolean skip_none: Skip conversion if value is None

    :return: Converted value
    :rtype: boolean
    """
    return ToBool(skip_none=skip_none).convert(value)


def _to_int(value, skip_none=False):
    """Method to made conversion to integer

    :param value: Some value to convert
    :param boolean skip_none: Skip conversion if value is None

    :return: Converted value
    :rtype: integer
    """
    if value is None and skip_none or isinstance(value, int):
        return value
    if isinstance(value, six.string_types):
        try:
            return int(value)
        except ValueError:
            raise ValueError('Value "{}" is not an integer number representation'.format(str(value)))
    raise Exception('Object "{}" with value "{}" cannot be converted to int'.format(type(value).__name__, str(value)))


def _to_float(value, skip_none=False):
    """Method to made conversion to float

    :param value: Some value to convert
    :param boolean skip_none: Skip conversion if value is None

    :return: Converted value
    :rtype: float
    """
    if value is None and skip_none or isinstance(value, float):
        return value
    if isinstance(value, (six.string_types, int)):
        try:
            return float(value)
        except ValueError:
            raise ValueError('Value "{}" is not a floating point number representation'.format(str(value)))
    raise Exception('Object "{}" with value "{}" cannot be converted to float'.format(type(value).__name__, str(value)))


def convert_value(value):
    """convert value to one of the types [bool, int, float, str]"""
    converters = [_to_bool, _to_int, _to_float, str]
    for converter in converters:
        try:
            return converter(value)
        except Exception:
            pass
    raise Exception('Can not convert type of: %s' % value)


def convert_dist_name(dist_name):
    """convert distname to regex expression"""
    replaces_list = ('[', '('), (']', ')'), (',', '|'), ('*', '([0-9]+)'), ('//', '/(.*/)?')
    regexp_body = reduce(lambda result, kv: result.replace(*kv), replaces_list, dist_name)
    regexp_start = '' if dist_name.startswith('//') else '^'
    regexp_end = '$'
    return regexp_start + regexp_body + regexp_end
